mapper.select:
select
a.task_result_id,
a.task_id,
a.task_name,
a.task_abnormal,
a.task_alarm,
a.run_execute,
a.cruise_task_time,
a.task_status,
a.cruise_result,
a.remark
from t_cruise_task_result a
where 1 = 1
and a.task_result_id = #{taskResultId, jdbcType=VARCHAR}
and a.task_id = #{taskId, jdbcType=VARCHAR}
and a.task_name = #{taskName, jdbcType=VARCHAR}
and a.task_abnormal = #{taskAbnormal, jdbcType=INTEGER}
and a.task_alarm = #{taskAlarm, jdbcType=INTEGER}
and a.run_execute = #{runExecute, jdbcType=VARCHAR}
and a.cruise_task_time = #{cruiseTaskTime, jdbcType=TIMESTAMP}
and a.task_status = #{taskStatus, jdbcType=INTEGER}
and a.cruise_result = #{cruiseResult, jdbcType=INTEGER}
and a.remark = #{remark, jdbcType=VARCHAR}

